        UNION { VALUES ?root { wd:Q514654 wd:Q971128 wd:Q1426478 wd:Q17018254 wd:Q5977448 wd:Q30689475 wd:Q136206072 wd:Q739462 wd:Q5597170 wd:Q201721 wd:Q504353 wd:Q28811699 wd:Q105227079 wd:Q5610729 wd:Q2497721 wd:Q83478 wd:Q17019511 wd:Q765994 wd:Q17077830 wd:Q63993355 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q514654 wd:Q971128 wd:Q1426478 wd:Q17018254 wd:Q5977448 wd:Q30689475 wd:Q136206072 wd:Q739462 wd:Q5597170 wd:Q201721 wd:Q504353 wd:Q28811699 wd:Q105227079 wd:Q5610729 wd:Q2497721 wd:Q83478 wd:Q17019511 wd:Q765994 wd:Q17077830 wd:Q63993355 } BIND(?root AS ?item) }
